# Generated by tools/build_raid_combat.py; regenerate after combat changes.
import json
import random
from pathlib import Path
from types import SimpleNamespace

HP = 5
ROUNDS_RAID = 10
RAID_PLAYER_HP = 10
POWER_HIT_CAP = 0.05
POWER_HIT_PER_POINT = 0.002
_RANK = {"Egg": 0, "Fresh": 1, "InTraining": 2, "Rookie": 3,
         "Champion": 4, "Ultimate": 5, "Mega": 6}
with open(Path(__file__).with_name("raid_species.json"), encoding="utf-8") as f:
    SPECIES = json.load(f)
data = SimpleNamespace(record_for=lambda num: SPECIES.get(str(num), {}))

def _tri(mine, theirs):
    """The attribute triangle: ±0.05 hit chance."""
    a, b = ((mine or '').lower(), (theirs or '').lower())
    if (a, b) in (('vaccine', 'virus'), ('virus', 'data'), ('data', 'vaccine')):
        return 0.05
    if (a, b) in (('virus', 'vaccine'), ('data', 'virus'), ('vaccine', 'data')):
        return -0.05
    return 0

class Side:
    """One combatant, normalized: a live Pet, a lobby card, or a wild foe."""

    def __init__(self, num, name='', stage='', attribute='', strength=4, strength_max=4, hunger=4, hunger_max=4, energy=5, energy_max=5, weight=None, base_weight=10, trainings_cur=0, trainings_total=0, battles=0, wins=0, hit_type='normal', boss=False, powers=None, hp=None):
        self.num = num
        self.powers = dict(powers or {})
        self.hp = HP if hp is None else hp
        self.name = name or (data.record_for(num).get('name', '?') if num >= 0 else '?')
        self.stage = stage
        self.attribute = attribute
        self.strength, self.strength_max = (strength, max(1, strength_max))
        self.hunger, self.hunger_max = (hunger, max(1, hunger_max))
        self.energy, self.energy_max = (energy, max(1, energy_max))
        self.base_weight = base_weight
        self.weight = base_weight if weight is None else weight
        self.trainings_cur = trainings_cur
        self.trainings_total = trainings_total
        self.battles, self.wins = (battles, wins)
        self.hit_type = 'mega' if battles >= 999 else hit_type
        self.boss = boss

    @classmethod
    def wild(cls, num, boss=False):
        """A wild foe: its species at ideal condition, untrained.  (The
        classic roster carries no meter columns -- ideal condition IS the
        definition, so the perfect gauges are pinned directly.)"""
        rec = data.record_for(num)
        return cls(num, name=rec.get('name', '?'), stage=rec.get('stage', ''), attribute=rec.get('attribute', 'Free'), strength=4, strength_max=4, hunger=4, hunger_max=4, energy=5, energy_max=5, weight=10, base_weight=10, boss=boss)

    @classmethod
    def of_card(cls, card):
        """A lobby peer's relayed card (clamped upstream)."""
        return cls(int(card.get('num', 0)), name=card.get('name', '?'), stage=card.get('stage', 'Child'), attribute=card.get('attribute', 'Free'), strength=card.get('strength', 4), strength_max=card.get('strength_max', 4), hunger=card.get('hunger', 4), hunger_max=card.get('hunger_max', 4), energy=card.get('energy', 5), energy_max=card.get('energy_max', 5), weight=card.get('weight', 10), base_weight=card.get('base_weight', 10), trainings_cur=card.get('trainings_cur', 0), trainings_total=card.get('trainings_total', 0), battles=card.get('battles', 0), wins=card.get('wins', 0), hit_type=card.get('hit_type', 'normal'), powers=card.get('powers'), hp=card.get('hp', HP))

    def _rank(self):
        return _RANK.get(self.stage, 3)

    def _condition(self):
        """The meter terms of the hit formula (each 0..0.1 - 0.05)."""
        st = self.strength / self.strength_max * 0.1 - 0.05
        hu = self.hunger / self.hunger_max * 0.1 - 0.05
        en = self.energy / self.energy_max * 0.1 - 0.05
        if self.base_weight > 0:
            w = (1 - min(1, abs(self.weight - self.base_weight) / 15)) * 0.2 - 0.1
        else:
            w = 0
        return st + hu + en + w

    def hit_chance(self, other):
        wr = self.wins / self.battles if self.battles > 0 else 0.5
        p = 0.3 + (wr - 0.5) * 0.1 + (self._rank() - other._rank()) * 0.1 + min(self.trainings_cur / 999 * 0.1, 0.1) + min(self.trainings_total / 9999 * 0.2, 0.2) + self._condition() + _tri(self.attribute, other.attribute) + (0.1 if self.hit_type == 'mega' else 0.0) + (-0.1 if other.hit_type == 'mega' else 0.0) + self.power_edge(other)
        return min(1.0, max(0.0, p))

    def power_edge(self, other):
        """Battle call #21 = B: power earned against the FOE's attribute."""
        pts = max(0, int(self.powers.get(other.attribute, 0) or 0))
        return min(POWER_HIT_CAP, pts * POWER_HIT_PER_POINT)

    def roll_damage(self, rng):
        if self.hit_type == 'mega':
            return 2 if rng() < 0.9 else 1
        return 2 if rng() < 0.5 else 1

def generate_raid(me, boss, rng=None):
    """The raid attempt: 10 rounds against an effectively-invincible boss.
    The player fights from 10 HP; the boss never falls IN the fight -- the
    raw damage landed here is what the shared pool eats (x5000 x stage-mult,
    applied server-side).  Returns (rounds, raw_dealt, my_end_hp)."""
    rng = rng or random.random
    my_hp = RAID_PLAYER_HP
    p_me, p_boss = (me.hit_chance(boss), boss.hit_chance(me))
    seq = []
    dealt = 0
    for _ in range(ROUNDS_RAID):
        if my_hp <= 0:
            break
        my_dmg = me.roll_damage(rng)
        my_hit = rng() < p_me
        boss_dmg = boss.roll_damage(rng)
        boss_hit = rng() < p_boss
        if my_hit:
            dealt += my_dmg
        if boss_hit:
            my_hp -= boss_dmg
        seq.append((my_hit, my_dmg, boss_hit, boss_dmg))
    return (seq, dealt, max(0, my_hp))

def volley(save, boss_num, rng=None):
    num = save.get("num")
    if type(num) is not int or str(num) not in SPECIES:
        raise ValueError("unknown cloud species")
    rec = SPECIES[str(num)]
    if rec["stage"] not in ("InTraining", "Rookie", "Champion", "Ultimate", "Mega") or save.get("dead") or save.get("asleep"):
        raise ValueError("pet unavailable")
    def number(key, default, lo=0, hi=999999):
        value = save.get(key, default)
        if not isinstance(value, (int, float)) or not __import__("math").isfinite(value):
            raise ValueError("invalid cloud stat")
        return max(lo, min(hi, value))
    me = Side(num, name=rec["name"], stage=rec["stage"], attribute=rec["attribute"],
              strength=number("strength", 4, hi=4), hunger=number("hunger", 4, hi=4),
              energy=number("energy", 0, hi=rec["max_energy"]), energy_max=rec["max_energy"],
              weight=number("weight", rec["base_weight"]), base_weight=rec["base_weight"],
              trainings_cur=number("stage_trainings", 0), trainings_total=number("total_trainings", 0),
              battles=number("battles", 0), wins=number("wins", 0),
              hit_type=save.get("saved_hit_type", "normal"),
              powers={"Vaccine": number("vaccine", 0), "Data": number("data_power", 0),
                      "Virus": number("virus", 0)})
    return generate_raid(me, Side.wild(boss_num, boss=True), rng=rng)[1], num
